-- Pacote de apresentação 2025. Somente resultados congelados; não consulta tabelas de atletas/resultados.
-- Troque os IDs explicitamente depois de revisar e congelar novas coletas. Nada muda na web ao executar/congelar.
WITH b AS (SELECT payload FROM estudo.web_bases WHERE ano=2025),
r AS (SELECT * FROM estudo.notebook_runs WHERE frozen AND status='ok' AND NOT truncated AND id IN (6,7,8,15,16,17,25)),
m AS (
SELECT 'sexo_2024' AS serie,'F' AS categoria,jsonb_build_object('valor',v->'porcentagem','contagem',v->'total','denominador',(SELECT sum((x->>'total')::bigint) FROM jsonb_array_elements(r.result->'rows') x WHERE x->>'versao'='DataGrip 2024'),'fonte','Notebook · execução #6','nota','Participações tratadas; todas as categorias de sexo no denominador. Em 2025, exige tempo positivo.') AS atual FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows') v WHERE r.id=6 AND v->>'versao'='DataGrip 2024' AND v->>'genero'='F'
UNION ALL
SELECT 'sexo_2024' AS serie,'M' AS categoria,jsonb_build_object('valor',v->'porcentagem','contagem',v->'total','denominador',(SELECT sum((x->>'total')::bigint) FROM jsonb_array_elements(r.result->'rows') x WHERE x->>'versao'='DataGrip 2024'),'fonte','Notebook · execução #6','nota','Participações tratadas; todas as categorias de sexo no denominador. Em 2025, exige tempo positivo.') AS atual FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows') v WHERE r.id=6 AND v->>'versao'='DataGrip 2024' AND v->>'genero'='M'
UNION ALL
SELECT 'sexo_2025' AS serie,'F' AS categoria,jsonb_build_object('valor',v->'porcentagem','contagem',v->'total','denominador',(SELECT sum((x->>'total')::bigint) FROM jsonb_array_elements(r.result->'rows') x WHERE x->>'versao'='DataGrip 2025 (tempo positivo)'),'fonte','Notebook · execução #6','nota','Participações tratadas; todas as categorias de sexo no denominador. Em 2025, exige tempo positivo.') AS atual FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows') v WHERE r.id=6 AND v->>'versao'='DataGrip 2025 (tempo positivo)' AND v->>'genero'='F'
UNION ALL
SELECT 'sexo_2025' AS serie,'M' AS categoria,jsonb_build_object('valor',v->'porcentagem','contagem',v->'total','denominador',(SELECT sum((x->>'total')::bigint) FROM jsonb_array_elements(r.result->'rows') x WHERE x->>'versao'='DataGrip 2025 (tempo positivo)'),'fonte','Notebook · execução #6','nota','Participações tratadas; todas as categorias de sexo no denominador. Em 2025, exige tempo positivo.') AS atual FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows') v WHERE r.id=6 AND v->>'versao'='DataGrip 2025 (tempo positivo)' AND v->>'genero'='M'
UNION ALL
SELECT 'distancias_faixas' AS serie,'Até 5 km' AS categoria,jsonb_build_object('valor',v->'perc','contagem',v->'total','denominador',(SELECT sum((x->>'total')::bigint) FROM jsonb_array_elements(r.result->'rows') x),'fonte','Notebook · execução #15','nota','Faixas legadas de distância, preservadas no notebook.') AS atual FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows') v WHERE r.id=15 AND v->>'percurso'='< 6'
UNION ALL
